changeSet.sql:
-- Payroll permissions (hrm-service, schema `payroll`; comfy-payroll-architecture.md ARCH-02). INSERT INTO identity.permission (permission_code, scope, description) VALUES ('HR_RECORD_READ', 'BUSINESS', 'read individual pay, contracts, bank details, payroll audit log'), ('HR_RECORD_WRITE', 'BUSINESS', 'write employee profile, contracts, allowances, leave quotas'), ('PAYROLL_CONFIG_WRITE', 'BUSINESS', 'write payroll config and payroll reference data'), ('PAYROLL_PROCESS', 'BUSINESS', 'periods, roster, timesheet, manual items, payroll runs'), ('PAYROLL_APPROVE', 'BUSINESS', 'lock, unlock, mark paid, acknowledge warnings'), ('PAYSLIP_ISSUE', 'BUSINESS', 'generate and send payslips'), ('PAYROLL_REPORT_READ', 'BUSINESS', 'business-wide aggregate labour-cost reports'), ('TIMESHEET_READ', 'BRANCH', 'view roster and timesheet at a branch'), ('TIMESHEET_EDIT', 'BRANCH', 'edit roster and timesheet at a branch'), ('LABOR_COST_READ', 'BRANCH', 'branch aggregate labour cost');
GRANT SELECT ON identity.permission TO svc_hrm; GRANT SELECT ON identity.position_permission TO svc_hrm; GRANT SELECT ON identity.permission_revision TO svc_hrm;
-- Like-for-like seeding, so DEC-05 ("only admin and HR see individual pay") holds on day one. -- The existing grant triggers audit these rows and bump permission_revision.
-- Positions with a live PERMISSION_GRANT (the de-facto admins) receive the 7 business payroll permissions. INSERT INTO identity.position_permission (position_id, business_id, permission_code, scope) SELECT g.position_id, g.business_id, p.permission_code, 'BUSINESS' FROM identity.position_permission g CROSS JOIN (VALUES ('HR_RECORD_READ'), ('HR_RECORD_WRITE'), ('PAYROLL_CONFIG_WRITE'), ('PAYROLL_PROCESS'), ('PAYROLL_APPROVE'), ('PAYSLIP_ISSUE'), ('PAYROLL_REPORT_READ')) AS p(permission_code) WHERE g.permission_code = 'PERMISSION_GRANT' AND g.revoked_at IS NULL ON CONFLICT (position_id, permission_code) WHERE revoked_at IS NULL DO NOTHING;
-- Positions with a live CLOSE_REVIEW (the de-facto branch managers) receive the three branch payroll -- permissions, which apply at every branch where a staff member holds the position - never HR_RECORD_READ. INSERT INTO identity.position_permission (position_id, business_id, permission_code, scope) SELECT g.position_id, g.business_id, p.permission_code, 'BRANCH' FROM identity.position_permission g CROSS JOIN (VALUES ('TIMESHEET_READ'), ('TIMESHEET_EDIT'), ('LABOR_COST_READ')) AS p(permission_code) WHERE g.permission_code = 'CLOSE_REVIEW' AND g.revoked_at IS NULL ON CONFLICT (position_id, permission_code) WHERE revoked_at IS NULL DO NOTHING;
